export function marketingCopy(locale: FlashFluentMarketingLocale, source: string, variables: Record<string, string> = {}) {
  let translated = copy[locale]?.[source] ?? copy.en[source] ?? source;
  for (const [name, value] of Object.entries(variables)) translated = translated.replaceAll(`{${name}}`, value);
  return translated;
}
